var QueryUtils={uuidv4:require("uuid").v4,moment:require("moment"),mysql:require("mysql"),con:"",tokens:[],init:function(client_id,ilias_installation_dir){var fs=require("fs"),ini=require("ini"),util=require("util"),client_ini=ini.parse(fs.readFileSync(ilias_installation_dir+"/data/"+client_id+"/client.ini.php","utf-8"));this.con=this.mysql.createPool({host:client_ini.db.host,user:client_ini.db.user,database:client_ini.db.name,password:client_ini.db.pass}),this.con.query=util.promisify(this.con.query)},writeChatServerConfig:async function(ip,port,protocol,host){var config={ip:ip,port:port,protocol:protocol,host:host};for(var name in config)await this.con.query("INSERT INTO sr_chat_config (name, value) VALUES (?, ?) ON DUPLICATE KEY UPDATE value = ?",[name,config[name],config[name]])},getOldMessages:async function(chat_room_id){var con=this.con,moment=this.moment,rows=await con.query('SELECT m.*, u.login, u.firstname, u.lastname, p.value FROM sr_chat_message m LEFT JOIN usr_data u ON u.usr_id = m.usr_id LEFT JOIN usr_pref p ON p.usr_id = u.usr_id AND p.keyword = "public_profile" AND (p.value = "y" OR p.value = "g") WHERE m.chat_room_id = ? ORDER BY sent_at ASC',[chat_room_id]);return rows=rows.map(function(row){if(null==row.login)var public_name="[deleted]";else if(null==row.value)public_name=row.login;else public_name=row.firstname+" "+row.lastname;return Object.assign({},row,{sent_at:moment(row.sent_at).format("HH:mm"),public_name:public_name})})},loadTokens:async function(){let utils=this;var rows=await this.con.query("SELECT * FROM sr_chat_token");utils.tokens=[],rows.forEach(function(element){utils.tokens[element.token]=element}),await utils.cleanupTokens()},cleanupTokens:async function(){var ts=Math.round((new Date).getTime()/1e3);await this.con.query("DELETE FROM sr_chat_token WHERE valid_until_unix < ?",[ts])},checkAndFetchToken:async function(token){var ts=Math.round((new Date).getTime()/1e3);token in this.tokens||await this.loadTokens();var loaded_token=this.tokens[token];if(void 0!==loaded_token&&loaded_token.valid_until_unix>ts)return loaded_token;throw new Error("Token invalid"+(void 0!==loaded_token?" (expired)":""))},insertMessage:async function(chat_room_id,usr_id,msg,sent_at){await this.con.query("INSERT INTO sr_chat_message (id, chat_room_id, usr_id, message, sent_at) VALUES (?, ?, ?, ?, ?)",[this.uuidv4(),chat_room_id,usr_id,msg,sent_at])}};module.exports=QueryUtils;